shell_commands.command:
cd /testbed && patch -p1 <<'PATCH'
--- a/test/xchar-test.cc
+++ b/test/xchar-test.cc
@@ -440,6 +440,41 @@
   EXPECT_EQ(fmt::format(loc, "{:8L}", 1230.0), "   1~230");
 }

+TEST(locale_test, localized_double_alignment) {
+  auto loc = std::locale(std::locale(), new special_grouping<char>());
+  struct {
+    double value;
+    const char* expected;
+  } cases[] = {{-119.921, "-119.921"}, {2194.139, "2,194.139"},
+               {-57.639, "-57.639"},   {-5.980, "-5.980"},
+               {-2.119, "-2.119"},     {0.295, "0.295"},
+               {1.295, "1.295"},       {-0.295, "-0.295"},
+               {0.0, "0.000"}};
+  for (auto test : cases) {
+    auto expected = std::string(test.expected);
+    EXPECT_EQ(std::string(19 - expected.size(), ' ') + expected,
+              fmt::format(loc, "{:19.3Lf}", test.value));
+  }
+  EXPECT_EQ("1.295    ", fmt::format(loc, "{:<9.3Lf}", 1.295));
+  EXPECT_EQ("  1.295  ", fmt::format(loc, "{:^9.3Lf}", 1.295));
+  EXPECT_EQ("-0001.295", fmt::format(loc, "{:09.3Lf}", -1.295));
+  EXPECT_EQ("    1.295", fmt::format(loc, "{:9.3Lf}", 1.295f));
+  EXPECT_EQ("    1.295", fmt::format(loc, "{:9.3Lf}", 1.295L));
+
+  auto punct_loc = std::locale(std::locale(), new numpunct<char>());
+  EXPECT_EQ("   1?234", fmt::format(punct_loc, "{:8L}", 1.234));
+}
+
+TEST(locale_test, localized_wdouble_alignment) {
+  auto loc = std::locale(std::locale(), new numpunct<wchar_t>());
+  EXPECT_EQ(L"    0?295", fmt::format(loc, L"{:9.3Lf}", 0.295));
+  EXPECT_EQ(L"    1?295", fmt::format(loc, L"{:9.3Lf}", 1.295));
+  EXPECT_EQ(L"2~194?139", fmt::format(loc, L"{:9.3Lf}", 2194.139));
+  EXPECT_EQ(L"1?295    ", fmt::format(loc, L"{:<9.3Lf}", 1.295));
+  EXPECT_EQ(L"  1?295  ", fmt::format(loc, L"{:^9.3Lf}", 1.295));
+}
+
 TEST(locale_test, format) {
   auto loc = std::locale(std::locale(), new numpunct<char>());
   EXPECT_EQ("1234567", fmt::format(std::locale(), "{:L}", 1234567));
PATCH
cmake -B build -S . && cmake --build build --parallel 4 --target xchar-test && build/bin/xchar-test --gtest_filter='locale_test.localized_*alignment'

cd /testbed && python3 - <<'PY'
from pathlib import Path
import difflib
import subprocess
path = Path('test/xchar-test.cc')
old = path.read_text()
needle = 'TEST(locale_test, format) {\n'
addition = '''TEST(locale_test, localized_double_alignment) {
  auto loc = std::locale(std::locale(), new special_grouping<char>());
  struct {
    double value;
    const char* expected;
  } cases[] = {{-119.921, "-119.921"}, {2194.139, "2,194.139"},
               {-57.639, "-57.639"},   {-5.980, "-5.980"},
               {-2.119, "-2.119"},     {0.295, "0.295"},
               {1.295, "1.295"},       {-0.295, "-0.295"},
               {0.0, "0.000"}};
  for (auto test : cases) {
    auto expected = std::string(test.expected);
    EXPECT_EQ(std::string(19 - expected.size(), ' ') + expected,
              fmt::format(loc, "{:19.3Lf}", test.value));
  }
  EXPECT_EQ("1.295    ", fmt::format(loc, "{:<9.3Lf}", 1.295));
  EXPECT_EQ("  1.295  ", fmt::format(loc, "{:^9.3Lf}", 1.295));
  EXPECT_EQ("-0001.295", fmt::format(loc, "{:09.3Lf}", -1.295));
  EXPECT_EQ("    1.295", fmt::format(loc, "{:9.3Lf}", 1.295f));
  EXPECT_EQ("    1.295", fmt::format(loc, "{:9.3Lf}", 1.295L));

  auto punct_loc = std::locale(std::locale(), new numpunct<char>());
  EXPECT_EQ("   1?234", fmt::format(punct_loc, "{:8L}", 1.234));
}

TEST(locale_test, localized_wdouble_alignment) {
  auto loc = std::locale(std::locale(), new numpunct<wchar_t>());
  EXPECT_EQ(L"    0?295", fmt::format(loc, L"{:9.3Lf}", 0.295));
  EXPECT_EQ(L"    1?295", fmt::format(loc, L"{:9.3Lf}", 1.295));
  EXPECT_EQ(L"2~194?139", fmt::format(loc, L"{:9.3Lf}", 2194.139));
  EXPECT_EQ(L"1?295    ", fmt::format(loc, L"{:<9.3Lf}", 1.295));
  EXPECT_EQ(L"  1?295  ", fmt::format(loc, L"{:^9.3Lf}", 1.295));
}

'''
assert old.count(needle) == 1
new = old.replace(needle, addition + needle)
diff = ''.join(difflib.unified_diff(old.splitlines(True), new.splitlines(True), fromfile='a/'+str(path), tofile='b/'+str(path)))
subprocess.run(['patch', '-p1'], input=diff, text=True, check=True)
PY
cmake --build build --parallel 4 --target xchar-test && build/bin/xchar-test --gtest_filter='locale_test.localized_*alignment'

